// --- Later, I want to allow passing multiple TProcSpecs
//     string is a glob pattern or file path

export type TProcSpec = [CFileHandler, (TGlobPattern | TGlobPattern[])]
export type TProcResult = [boolean, string]
export type TCallback = (path: string, hResult: TExecResult) => void
export type TCounts = {
	ok: number
	notNeeded: number
	processed: number
	err: number
	}

export const procFiles = async (
		procSpec: TProcSpec,
		hOptions: hash = {}
		): AutoPromise<[
			TCounts,         // ok, notNeeded, processed, err
			number,          // seconds taken
			TExecResult[],  // all results
			]> => {

	type opt = {
		quiet: boolean
		verbose: boolean
		maxRunning: number
		callback: (TCallback | undefined)
		box: boolean
		}
	const {quiet, verbose, maxRunning, callback, box
		} = getOptions<opt>(hOptions, {
			quiet: false,
			verbose: false,
			maxRunning: Infinity,
			callback: undef,
			box: false
			})

	assert(!(quiet && verbose), "Can't use both quiet and verbose")
	const [handler, globPat] = procSpec
	const {op} = handler

	const timer = new CTimer()

	// --- NOTE: We need array lPaths to index into later

	const lPaths = Array.from(allFilesMatching(globPat))

	const hCounts: TCounts = {
		ok:        0,
		notNeeded: 0,
		processed: 0,
		err:       0
		}

	if (lPaths.length === 0) {
		if (verbose) {
			LOG(`(${op}:{cyan} - No files match`)
		}
		if (box) {
			endBox()
		}
		return [hCounts, timer.timeTaken(), []]
	}

	const results=[];for (const path of lPaths) {
		results.push(() => handler.handleFile(path, hOptions))
	};const lThunks =results

	// --- NOTE: if success is true, str is a file path
	//           if success is false, str is an error message

	const lAllResults: TExecResult[] = []
	if (box) {
		const title: string = isArray(globPat) ? globPat.join(' ') : globPat
		beginBox(handler.op + ' ' + title)
	}

	// --- hResult is a TExecResult
	for await (const result of allPromiseResults(lThunks, maxRunning)) {
		const [resolved, value, i] = result
		const path = lPaths[i]
		if (box) {
			beginBox(path)
		}
		if (resolved) {
			// --- value is a TExecResult hash
			const hResult = value
			if (defined(callback)) {
				callback(path, hResult)
			}
			lAllResults.push(hResult)
			const {success, notNeeded, infile} = hResult
			if (success) {
				hCounts.ok += 1
				if (notNeeded) {
					hCounts.notNeeded += 1
				}
				else {
					hCounts.processed += 1
				}
				if (verbose) {
					showOkResult(handler, path, hResult, hOptions)
				}
			}
			else {
				hCounts.err += 1
				showErrResult(handler, path, handler.getOutput(hResult), hOptions)
			}
		}
		else {
			// --- value is an error message
			const errMsg = getErrStr(value)
			const hResult = {
				success: false,
				timeTaken: timer.timeTaken(),
				stderr: errMsg
				}
			if (defined(callback)) {
				callback(path, hResult)
			}
			lAllResults.push(hResult)
			hCounts.err += 1
			showErrResult(handler, path, errMsg, hOptions)
		}
		if (box) {
			endBox()
		}
	}

	if (!quiet || (hCounts.err > 0)) {
		showFinalResult(
			op, globPat, hCounts,
			timer.timeTaken(), verbose)
	}

	if (box) {
		endBox()
	}

	return [
		hCounts,
		timer.timeTaken(),
		lAllResults
		]
}

// ---------------------------------------------------------------------------
// ASYNC

export const procOneFile = async (
		path: string,
		handler: CFileHandler,
		hOptions: hash = {}
		): AutoPromise<TExecResult> => {

	const [hCounts, secs, lResults] = await procFiles([handler, path], hOptions)
	return lResults[0]
}

// ---------------------------------------------------------------------------

const prelog = (
		op: string,
		path: string,
		): void => {

	writeln(f`${op}:{cyan} ${toRelPath(path)}`)
	return
}

// ---------------------------------------------------------------------------

const postlog = (hResult: TExecResult): void => {

	const {success, notNeeded, timeTaken} = hResult
	if (success) {
		if (notNeeded) {
			writeln(f`${' - not needed'}:{yellow} (${timeTaken} secs.)`)
		}
		else {
			writeln(f`${' - OK'}:{green} (${timeTaken} secs.)`)
		}
	}
	else {
		writeln(f`${' - FAILED'}:{red} (${timeTaken} secs.)`)
	}
	return
}

// ---------------------------------------------------------------------------

const showOkResult = (
		handler: CFileHandler,
		path: string,
		hResult: TExecResult,
		hOptions: hash = {}
		): void => {

	if (hResult.notNeeded) {
		return
	}
	const output = handler.getOutput(hResult)
	if (defined(output) && nonEmpty(output)) {
		LOGVALUE(output, 'OUTPUT', {escape: false})
	}
	return
}

// ---------------------------------------------------------------------------

const showErrResult = (
		handler: CFileHandler,
		path: string,
		errMsg: string,
		hOptions: hash = {}
		): void => {

	if (errMsg.includes('\n')) {
		LOGVALUE(errMsg, 'ERROR OUTPUT', {escape: false})
	}
	else {
		ERR(`ERROR: ${errMsg}`)
	}
	return
}

// ---------------------------------------------------------------------------

let headerPrinted = false

const showFinalResult = (
		op: string,
		globPat: string | string[],
		hCounts: hashof<number>,
		timeTaken: number,        // --- in secs
		verbose: boolean = false
		): void => {

	resetLine()
	if (verbose) {
		return
	}
	if (!headerPrinted) {
		LOG('-'.repeat(46))
		LOG([
			sprintf('%6s', 'secs.'),
			sprintf('%-14s', 'op'),
			sprintf('%3s', 'nnd'),
			sprintf('%3s', 'OK'),
			sprintf('%3s', 'Bad'),
			'file(s)'
		].join(' '))
		LOG('-'.repeat(46))
		headerPrinted = true
	}
	const {ok, notNeeded, err} = hCounts
	LOG([
		sprintf('%.2f', timeTaken),
		cyan(sprintf('%-14s', op)),
		sprintf('%3d', hCounts.notNeeded),
		(ok === 0)  ? sprintf('%3d', ok)  : green(sprintf('%3d', ok)),
		(err === 0) ? sprintf('%3d', err) : red(sprintf('%3d', err)),
		isArray(globPat) ? globPat.join(' + ') : globPat
	].join(' '))
	return
}

// --- type TProcSpec = [CFileHandler, (string | string[])]
// ---------------------------------------------------------------------------
// ASYNC

export const execResult = async (
		handler: CFileHandler,
		path: string,
		hOptions: hash = {}
		): AutoPromise<TExecResult> => {

	return await handler.handleFile(path, hOptions)
}

// ---------------------------------------------------------------------------
// ASYNC

export const allExecResults = async function*(
		procSpec: TProcSpec,
		hOptions: hash = {},      // --- may contain 'transFunc', which
		maxRunning: number = 10  //     is passed to handleFile()
		): TAsyncIterator<TSettleResult<TExecResult>> {

	const [handler, pat] = procSpec
	const {op} = handler
	const results1=[];for (const path of allFilesMatching(pat)) {
		results1.push(async () => {
			return await handler.handleFile(path, hOptions)
		})
	};const lThunks: TThunk<TExecResult>[] =results1

	// --- allPromiseResults<TExecResult> yields items of type:
	//     TSettleResult<TExecResult>, i.e.
	//     [true, TExecResult, integer] | [false, string, integer]

	yield* allPromiseResults<TExecResult>(lThunks, maxRunning)
	return
}

